def transform(grid):
    g=[r[:] for r in grid]; n=len(g); m=len(g[0])
    flat=sum(g,[]); bg=max(set(flat),key=flat.count)
    cells=[(r,c) for r in range(n) for c in range(m) if g[r][c]!=bg]
    rs=[r for r,c in cells]; cs=[c for r,c in cells]
    r0,r1=min(rs),max(rs); c0,c1=min(cs),max(cs)
    a,b=sorted(set(g[r][c] for r,c in cells))
    out=[[bg]*m for _ in range(n)]
    split=(r0+r1)//2; shift=c1-c0
    for r,c in cells:
        nc=c+shift if r<=split else c
        out[r][nc]=b if g[r][c]==a else a
